import json, copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
out=ROOT/'output/tutoriais-2026';tmp=ROOT/'tmp/tutoriais-2026'
out.mkdir(parents=True,exist_ok=True);tmp.mkdir(parents=True,exist_ok=True)
videos=[]
def scene(title,speech,fields=None,action='Continuar',bullets=None):
 return dict(title=title,speech=speech,fields=fields or [],action=action,bullets=bullets or [])
def add(slug,title,scenes):
 videos.append(dict(slug=slug,title=title,scenes=copy.deepcopy(scenes)))
rules=scene('Entenda as regras dos atestados','Na agenda, a regra geral exige atestado clínico e, para atividades aquáticas, também dermatológico. O horário pode exigir ou dispensar cada tipo. Confira as exigências antes de agendar. Envie PDF legível, aguarde a validação e acompanhe a validade.',[['Regra geral','Clínico; dermatológico para atividades aquáticas'],['Regra do horário','Pode exigir ou dispensar cada tipo'],['Documento aceito','PDF legível da pessoa correta'],['Liberação','Validação e vigência, quando exigidas']], 'Conferir exigências')
add('01-cadastro-completo','Criar conta e completar cadastro',[
scene('Comece pela conta do responsável','Na página inicial, abra a opção de cadastro. O responsável pela conta deve ser maior de idade. Use seus dados verdadeiros. Crianças e adolescentes devem ser cadastrados como dependentes de um responsável adulto.',[['Responsável pela conta','Pessoa maior de idade'],['Dados da demonstração','Exemplos fictícios']], 'Criar cadastro'),
scene('Preencha a identificação','Informe seu nome completo, com pelo menos quatorze caracteres, seu CPF e a data de nascimento verdadeira. Se o CPF já tiver conta, use o login ou a recuperação de senha. Não crie outro cadastro para contornar o aviso.',[['Nome completo','Mariana Almeida de Souza — exemplo'],['CPF','CPF verdadeiro do responsável'],['Nascimento','Data verdadeira do responsável']], 'Conferir dados'),
scene('Defina sua senha e confirme','Crie uma senha com pelo menos seis caracteres e repita a mesma senha na confirmação. Leia e aceite os termos apresentados e conclua a verificação solicitada. Depois, clique para criar o cadastro.',[['Senha','Pelo menos 6 caracteres'],['Confirmar senha','Repita a mesma senha'],['Termos e verificação','Leia e confirme no formulário']], 'Criar cadastro'),
scene('Complete os dados pessoais','Se o sistema abrir a complementação do cadastro, preencha sexo, contatos, endereço e contato de emergência. Use endereço verdadeiro e confira CEP, número e bairro. O telefone de emergência deve ser diferente do WhatsApp do responsável.',[['Contatos','WhatsApp e e-mail verdadeiros'],['Endereço','CEP, logradouro, número e bairro'],['Emergência','Nome e telefone alternativo']], 'Completar cadastro'),
scene('Cartão SUS e condição declarada','Informe os quinze dígitos corretos do cartão SUS. Se precisar obter ou confirmar o número, procure uma UBS. Declare apenas a condição que se aplica à pessoa. O sistema admite uma condição por pessoa e exige documentação correspondente.',[['Cartão SUS','15 dígitos válidos'],['Condição','PCD, PLM ou PVS, quando aplicável'],['Documentação','Enviar e acompanhar a validação']], 'Salvar cadastro'),
rules,
scene('Confira o painel e as pendências','Salve e confira seus dados no painel. Cadastro completo não significa que todos os documentos foram validados. Leia os avisos de cartão SUS, atestados e condições. Resolva cada pendência pelo botão da pessoa correta.',[['Painel','Confira seus dados'],['Avisos','Leia as pendências indicadas'],['Documentos','Acompanhe análise e validade']], 'Abrir painel')])
add('02-novo-dependente','Adicionar um novo dependente',[
scene('Entre na conta do responsável','Faça login com o CPF e a senha do responsável adulto. Complete primeiro o cadastro do responsável, se solicitado. No painel, localize Meus dependentes e clique em Novo dependente.',[['Painel do usuário','Meus dependentes'],['Ação','Novo dependente']], 'Novo dependente'),
scene('Informe os dados do dependente','Preencha o nome completo, o CPF e o nascimento da própria pessoa que será dependente. Não use o CPF do responsável nesse campo. Dependentes podem ser maiores ou menores de idade. Confira os dados para evitar duplicidade.',[['Nome completo','Nome do dependente'],['CPF','CPF do próprio dependente'],['Nascimento','Data verdadeira']], 'Conferir identificação'),
scene('Confira contatos e endereço','Complete sexo, e-mail e endereço. O WhatsApp é preenchido com o número do responsável autenticado. Informe os quinze dígitos corretos do cartão SUS e um contato de emergência com telefone diferente do WhatsApp do responsável.',[['WhatsApp','Preenchido com o responsável'],['Cartão SUS','15 dígitos corretos'],['Endereço','Confira os dados completos'],['Emergência','Nome e telefone alternativo']], 'Preencher dados'),
scene('Informe o responsável e a condição','Preencha o nome e o CPF de pelo menos um responsável. Declare uma condição somente se ela se aplicar ao dependente. A documentação da condição e os atestados são próprios de cada pessoa, não da conta inteira.',[['Responsável 1 ou 2','Nome e CPF de pelo menos um'],['Condição declarada','Uma condição, quando aplicável'],['Documentos','Pertencem ao dependente']], 'Salvar dependente'),
scene('Se o CPF já estiver cadastrado','Se houver aviso de CPF já cadastrado, confira a pessoa e o vínculo. Não invente outro CPF nem altere a data de nascimento. Quando necessário, use a transferência de responsabilidade ou procure a administração para regularizar o vínculo.',[['Aviso','CPF já cadastrado'],['Providência','Conferir vínculo e responsável'],['Alternativa','Transferência ou administração']], 'Conferir vínculo'),
rules,
scene('Confira o novo dependente','Após salvar, confira o dependente no painel. Use os botões da linha dessa pessoa para atualizar dados, enviar documentos e acompanhar os avisos. Antes de inscrever ou agendar, confira requisitos, períodos e vagas disponíveis.',[['Meus dependentes','Pessoa cadastrada'],['Documentos','Usar os botões dessa pessoa'],['Agenda e cursos','Conferir requisitos e vagas']], 'Abrir dados do dependente')])
add('03-login','Entrar no sistema',[
scene('Abra a janela de login','Na página inicial, abra a opção de entrar no sistema. Use a conta do responsável adulto. Para administrar dependentes, entre com a sua própria conta de responsável e selecione a pessoa no painel.',[['Acesso','Entrar no sistema'],['Conta','Responsável adulto']], 'Entrar'),
scene('Informe CPF e senha','Digite o CPF da conta e a senha cadastrada. Confira os números do CPF e a digitação da senha. Complete a verificação solicitada pelo formulário e clique em entrar.',[['CPF','CPF da conta'],['Senha','Sua senha cadastrada'],['Verificação','Conclua quando solicitada']], 'Entrar'),
scene('Leia o resultado do acesso','Se aparecer CPF ou senha inválidos, confira a digitação. Caso tenha esquecido a senha, use Recuperar senha. Se houver restrição de cadastro ou vínculo, siga o aviso; redefinir a senha não corrige dados pessoais nem permissões.',[['CPF ou senha inválidos','Conferir os dados'],['Esqueceu a senha?','Usar Recuperar senha'],['Outro bloqueio','Seguir a orientação do aviso']], 'Recuperar senha'),
scene('Conclua o que estiver pendente','Após entrar, o sistema pode solicitar a complementação do cadastro. Preencha os campos indicados e salve. No painel, confira os dados do titular e dos dependentes e leia os avisos antes de escolher uma atividade.',[['Cadastro incompleto','Completar e salvar'],['Painel','Titular e dependentes'],['Avisos','Verificar documentos']], 'Abrir painel'),
rules,
scene('Encerre a sessão ao terminar','Em computador compartilhado, não salve sua senha no navegador. Ao terminar, clique em Sair. Para cadastrar um dependente, permaneça na conta do responsável e use Novo dependente.',[['Computador compartilhado','Evite salvar a senha'],['Encerrar acesso','Clique em Sair']], 'Sair')])
add('04-recuperar-senha','Recuperar a senha da conta',[
scene('Quando recuperar a senha','Use a recuperação quando você já possui uma conta e esqueceu a senha ou não consegue entrar após conferir a digitação. O aviso CPF ou senha inválidos pode indicar senha incorreta; confira também o CPF antes de redefinir.',[['Esqueceu sua senha','Use a recuperação'],['CPF ou senha inválidos','Confira a digitação primeiro']], 'Recuperar senha'),
scene('Não confunda os avisos','O aviso de que o CPF já possui conta orienta usar a conta existente, com login ou recuperação. CPF cadastrado apenas como pessoa, vínculo de dependente, conta bloqueada e dados divergentes exigem a orientação específica do aviso. Trocar a senha não resolve essas situações.',[['CPF já possui conta','Entrar ou recuperar a senha'],['Sem conta ou vínculo pendente','Seguir o aviso específico'],['Dados divergentes','Conferir ou procurar administração']], 'Ler o aviso'),
scene('Confirme os dados da conta','Abra Recuperar senha. Informe o CPF da conta e a data de nascimento verdadeira no formato dia, mês e ano. Os dados precisam corresponder ao cadastro. Este fluxo confere esses dados diretamente; não depende de um link enviado por e-mail.',[['CPF','CPF da conta existente'],['Nascimento','DD/MM/AAAA conforme cadastro']], 'Confirmar dados'),
scene('Defina uma nova senha','Digite uma nova senha com pelo menos seis caracteres e repita exatamente o mesmo conteúdo na confirmação. Conclua a verificação apresentada e envie. Se a confirmação não corresponder, corrija os dois campos.',[['Nova senha','Pelo menos 6 caracteres'],['Confirmar nova senha','Repita exatamente'],['Verificação','Conclua no formulário']], 'Alterar senha'),
scene('Confira a mensagem final','Quando aparecer Senha alterada com sucesso, volte ao login e use a nova senha. Se o sistema não conseguir confirmar os dados, confira CPF e nascimento. Persistindo o problema, procure a administração; não crie conta duplicada.',[['Sucesso','Entrar com a nova senha'],['Dados não confirmados','Conferir CPF e nascimento']], 'Entrar'),
rules])
for slug,typ,label in [('05-atestado-clinico','clínico','clínico'),('06-atestado-dermatologico','dermatológico','dermatológico')]:
 add(slug,'Enviar ou atualizar atestado '+typ,[
 scene('Escolha a pessoa e o tipo de atestado',f'Entre no painel e localize a pessoa correta: você ou um dependente. Clique em Atualizar atestado {typ}. Confira o nome da pessoa no formulário. O documento enviado deve pertencer a ela.',[['Pessoa','Confira titular ou dependente'],['Ação','Atualizar atestado '+typ]],'Atualizar atestado '+typ),
 scene('Preencha conforme o documento','Informe a data de emissão que consta no atestado, o CRM do médico e onde ocorreu o atendimento. Selecione serviço público, clínica particular ou clínica de convênio, conforme o caso. Use o botão de interrogação para entender cada campo.',[['Data de emissão','Conforme o atestado'],['CRM do médico','Transcreva do documento'],['Local do atendimento','Selecione a opção correta'],['Observações','Informações complementares, se houver']], 'Conferir os dados'),
 scene('Selecione um PDF legível','No campo de arquivo, escolha o PDF do atestado da pessoa. Confira se o documento está completo e legível. Uma foto em JPG ou PNG precisa ser convertida para PDF antes do envio; apenas renomear a extensão não converte o arquivo.',[['Arquivo','atestado-exemplo.pdf'],['Formato','PDF verdadeiro e legível'],['Conteúdo','Documento completo da pessoa']], 'Selecionar PDF'),
 scene('Salve e aguarde a análise','Clique em Salvar atestados. Enviar o arquivo não o torna automaticamente validado. Ao substituir um PDF do mesmo tipo, o arquivo anterior é substituído e o novo volta para análise. Confira os avisos e a situação mostrada no painel.',[['Ação','Salvar atestados'],['Situação','Pendente de validação'],['Substituição','Novo documento será analisado']], 'Salvar atestados'),
 scene('Confira a validade definida pela equipe','Na validação, a equipe confere a data de emissão e define o prazo permitido no sistema: seis, doze, dezoito ou vinte e quatro meses. A validade é calculada a partir da emissão validada. O usuário acompanha a data final exibida; não escolhe a validade.',[['Equipe','Confere emissão e prazo'],['Prazo no sistema','6, 12, 18 ou 24 meses'],['Usuário','Acompanha a validade exibida']], 'Conferir validade'),
 rules,
 scene('Resolva vencimento ou reprovação',f'Se o atestado {typ} estiver vencido, reprovado ou ainda sem validação, siga o aviso antes de agendar um horário que o exige. Leia o motivo informado e envie o documento correto. Atestados de saúde e documentos de condição são analisados separadamente.',[['Vencido ou reprovado','Ler a orientação e atualizar'],['Pendente','Acompanhar a análise'],['Condição PCD, PLM ou PVS','Documentação separada']], 'Atualizar documento')])
for slug,code,label in [('07-condicao-pcd','PCD','Pessoa com Deficiência'),('08-condicao-plm','PLM','Pessoa com Laudo Médico de Doença'),('09-condicao-pvs','PVS','Pessoa em Vulnerabilidade Social')]:
 fields=[['Resumo da documentação','Descreva o que está enviando'],['Data de emissão','Conforme o documento, quando informada']]
 if code=='PVS':fields += [['CadÚnico / NIS','11 dígitos numéricos']]
 else:fields += [['CID declarado','Transcreva o código do documento'],['Doença declarada','Transcreva a informação do documento']]
 scenes=[scene('Selecione a pessoa e confira a condição',f'Para atualizar {label}, entre no painel e confira a pessoa correta. Nos dados dela, declare {code} somente se essa condição se aplica. O sistema permite uma condição por pessoa. Salve os dados e abra o botão de enviar ou atualizar documentação dessa condição.',[['Pessoa','Titular ou dependente correto'],['Condição',label],['Ação','Enviar/atualizar documentação']], 'Atualizar documentação'),
 scene('Preencha os dados da documentação',('Informe o resumo da documentação e o número do CadÚnico, NIS, com onze dígitos. Confira a data de emissão quando preenchida. Os dados precisam corresponder aos documentos enviados.' if code=='PVS' else 'Informe um resumo da documentação, o CID declarado e o nome da doença exatamente como constam no documento. Não invente um diagnóstico. Confira a data de emissão quando preenchida.'),fields,'Conferir documentos')]
 if code=='PCD':scenes.append(scene('Informe os tipos de deficiência','Para PCD, marque ao menos um tipo de deficiência correspondente à documentação. Essas informações também permitem que o sistema mostre avisos sobre barreiras de acessibilidade dos espaços. Confira cuidadosamente antes de salvar.',[['Tipos de deficiência','Marque os que constam na documentação'],['Finalidade','Validação e avisos de acessibilidade']], 'Conferir tipos'))
 scenes += [scene('Anexe os PDFs e salve','Selecione os documentos comprobatórios em PDF, completos e legíveis. Confira se pertencem à pessoa indicada. Leia e confirme a ciência do prazo no formulário. A documentação e os atestados aplicáveis podem ser analisados em até três dias úteis. A declaração da condição não substitui a documentação validada e vigente.',[['Arquivos','PDFs legíveis e completos'],['Situação após envio','Acompanhar análise'],['Validade','Conferir a vigência mostrada']], 'Enviar documentação'),
 scene('Entenda as vagas da condição',f'O sistema possui vagas por público: geral, PCD, PLM e PVS. A documentação validada de {code} permite concorrer às vagas correspondentes quando existirem, conforme os demais requisitos. Não há vaga automaticamente garantida: é preciso haver disponibilidade e concluir o procedimento no período correto.',[['Público da condição',code],['Requisitos','Documentação válida e demais regras'],['Disponibilidade','Vaga existente; reserva não é automática']], 'Consultar vagas'),
 scene('Pendências também afetam outras vagas','Ao declarar uma condição, a pessoa precisa manter a documentação correspondente validada e vigente para inscrições e agendamentos, inclusive quando tenta uma vaga geral. Pendência, reprovação ou vencimento devem ser regularizados. Os atestados clínico e dermatológico continuam sendo exigidos conforme as regras aplicáveis.',[['Condição declarada','Documentação validada e vigente'],['Vagas gerais','Também respeitam as pendências'],['Atestados de saúde','Regras próprias']], 'Conferir pendências'),rules]
 if code=='PCD':scenes.append(scene('Confira a acessibilidade do espaço','O sistema informa quando o espaço tem barreiras cadastradas para o tipo de deficiência declarado: acesso, rampas, sanitários ou equipamento de entrada na piscina, por exemplo. O aviso não bloqueia automaticamente a inscrição ou o agendamento. Converse com a equipe do local e confira as condições para sua participação.',[['Barreiras informadas','Acesso, sanitário, piscina e outras'],['Aviso de acessibilidade','Não bloqueia automaticamente'],['Antes de participar','Confirmar as condições com o local']], 'Consultar o espaço'))
 scenes.append(scene('Confira o resultado e mantenha atualizado','Após enviar, acompanhe a situação e as observações da equipe. Corrija o que for solicitado e atualize documentos quando necessário. A validação da condição não substitui inscrição, matrícula, disponibilidade de vagas, exigência de nível ou atestados de saúde.',[['Resultado','Pendente, validado ou reprovado'],['Manutenção','Atualizar conforme os avisos'],['Participação','Conferir todas as regras da atividade']], 'Acompanhar no painel'))
 add(slug,'Atualizar condição '+code+' — '+label,scenes)
for v in videos:
 for i,s in enumerate(v['scenes']):s['id']=i;s['video']=v['slug']
(tmp/'videos.json').write_text(json.dumps(videos,ensure_ascii=False,indent=2),encoding='utf-8')
(tmp/'narracoes.json').write_text(json.dumps([s for v in videos for s in v['scenes']],ensure_ascii=False),encoding='utf-8')
(out/'roteiros.json').write_text(json.dumps(videos,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(videos)} vídeos; {sum(len(v["scenes"]) for v in videos)} cenas')
